// Qualifiers: Pointer vs. Pointed-To
const int *ptr_to_const;      // Value constant, pointer mutable
int * const const_ptr;        // Pointer constant, value mutable
const volatile int * const fully_qualified;

// Complex: Array of Pointers to Qualified Type
// Arr is an array of 10 pointers to volatile int
volatile int *Arr[10];

// Complex: Function Returning a Qualified Pointer
// Getter returns a pointer to a constant char
const char * get_constant_string(void);

// Function Pointer Declaration using typedef
typedef int (*BinaryOp)(int, int);
BinaryOp adder = NULL;

// Volatile Pointer to Constant Memory (e.g., ROM lookup table)
// The data is const, but the pointer location must be accessed carefully (volatile)
const int * volatile lookup_table;

// Hardware Register definition (Pointer is const, pointed data is volatile)
#define REG_BASE 0xFF000000
volatile uint32_t * const STATUS_REG = (void*)REG_BASE;
